// Artifact integrity only: no compiler builds, minification or timing reruns.
import fs from 'node:fs';import {createHash} from 'node:crypto';
const here=import.meta.dirname,dir=here+'/results/stress',hash=b=>createHash('sha256').update(b).digest('hex');
const rows=fs.readFileSync(dir+'/observations.jsonl','utf8').trim().split('\n').filter(Boolean).map(JSON.parse),unique=new Map();
for(const r of rows){const key=r.name+'/'+r.mode,prior=unique.get(key);if(prior&&prior.sha256!==r.sha256)throw Error('Conflicting repeated observation '+key);unique.set(key,r)}
for(const [key,r] of unique){const file=here+'/.out/'+(r.mode==='solid'?'solid':'measured')+'/'+key+'.js',code=fs.readFileSync(file,'utf8').replace(/\/\/# sourceMappingURL=.*\n?$/,'');if(hash(code)!==r.sha256||Buffer.byteLength(code)!==r.full.raw)throw Error('Bundle hash/length mismatch '+key);if(r.runtime.raw+r.app_alone.raw+r.excluded_core.raw!==r.full.raw)throw Error('Raw attribution mismatch '+key);if(r.rendering.raw+r.excluded_core.raw!==r.full.raw)throw Error('Rendering attribution mismatch '+key);const spec=JSON.parse(fs.readFileSync(here+'/.out/apps/'+r.name+'/spec.json'));if(spec.n!==r.n||spec.seed!==r.seed||spec.onlyShape!==r.shape)throw Error('Spec mismatch '+key)}
const stoppedFile=dir+'/stopped.jsonl',stopped=fs.existsSync(stoppedFile)?fs.readFileSync(stoppedFile,'utf8').trim().split('\n').filter(Boolean).map(JSON.parse):[];
const result={verified_at:new Date().toISOString(),observations:unique.size,scope:'Actual minified file SHA-256 and raw length, disjoint raw byte accounting, and source spec identity. No size fits or compression results are recomputed; no project suites.',crossings:[...unique.values()].filter(r=>r.rendering.brotli>=512000).map(r=>({family:r.shape||'mixed',mode:r.mode,n:r.n,brotli:r.rendering.brotli})),compiler_limited:stopped.map(r=>({family:r.family,mode:r.mode,n:r.n}))};fs.writeFileSync(dir+'/integrity.json',JSON.stringify(result,null,2)+'\n');console.log('Verified',unique.size,'priced stress artifacts');
